use std::{rc::Rc as LocalRc,cell::RefCell as LocalCell,io::{Read,Write,Cursor},panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Clone)]struct Bytes(LocalRc<LocalCell<Vec<u8>>>);impl Write for Bytes{fn write(&mut self,b:&[u8])->std::io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn result(f:impl FnOnce())->String{match catch_unwind(AssertUnwindSafe(f)){Ok(())=>"ok".into(),Err(e)=>{let text=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");if text.contains("NullPointerException"){"NullPointerException".into()}else{format!("panic: {text}")}}}}
fn output(mut f:impl FnMut(&mut dyn XmlWriter))->Value{let mut m=MemoryXmlWriter::new();let mr=result(||f(&mut m));let units=m.getCodeUnits().iter().map(|v|format!("{v:04x}")).collect::<String>();let bytes=Bytes(LocalRc::new(LocalCell::new(vec![])));let mut b=BufferXmlWriter::new(Box::new(bytes.clone()));let br=result(||{f(&mut b);b.flush();});json!({"memoryResult":mr,"units":units,"bufferResult":br,"bytes":base64(&bytes.0.borrow())})}
fn pattern(p:&Value)->Option<Rc<RefCell<PatternFormatting>>>{if p["null"]==true{return None;}let mut f=PatternFormatting::PatternFormatting();f.setFillPattern(p["pattern"].as_i64().unwrap()as i32);f.setFillForegroundColor(p["fore"].as_i64().unwrap()as i32);f.setFillBackgroundColor(p["back"].as_i64().unwrap()as i32);if !p["gradient"].is_null(){let g=&p["gradient"];let bits=|k:&str|f32::from_bits(g[k].as_u64().unwrap()as u32);let gradient=XFGradient{isLinear:g["linear"].as_bool().unwrap(),degree:g["degree"].as_i64().unwrap()as i32,left:bits("left"),right:bits("right"),top:bits("top"),bottom:bits("bottom"),colorStops:g["stops"].as_array().unwrap().iter().map(|s|Rc::new(RefCell::new(ColorStop{color:s["color"].as_i64().unwrap()as i32,position:f32::from_bits(s["position"].as_u64().unwrap()as u32)}))).collect()};f.setXfGradient(Some(Rc::new(RefCell::new(gradient))));}Some(Rc::new(RefCell::new(f)))}
fn history(input:&Value)->Value{let mut label=FillsLabel::FillsLabel();let p=pattern(&input["fills"][3]).unwrap();let mut out=vec![];for i in 0..12{let f=if i==0{Some(Rc::new(RefCell::new(PatternFormatting::PatternFormatting())))}else if i==2{let mut f=PatternFormatting::PatternFormatting();f.setFillPattern(17);Some(Rc::new(RefCell::new(f)))}else if i%3==0{None}else if i%3==1{Some(p.clone())}else{Some(Rc::new(RefCell::new(p.borrow().clone())))};let mut id=None;let r=result(||id=Some(label.addForWrite(f)));let mut row=json!({"result":r});if let Some(id)=id{row["id"]=json!(id);}if i==5{p.borrow_mut().setFillForegroundColor(-16711936);}row["output"]=output(|w|label.write(w));out.push(row);}json!(out)}
fn formats(input:&Value,book:&Rc<KmoBook>)->Value{book.getXFManager().borrow().addFormat(164,"0.0000<&>\n".into());book.getXFManager().borrow().addFormat(165,"@😀".into());let mut label=NumFmtsLabel::NumFmtsLabel(book.clone());let mut out=vec![output(|w|label.write(w))];for id in input["formats"].as_array().unwrap(){label.addForWrite(id.as_i64().unwrap()as i16);out.push(output(|w|label.write(w)));}json!(out)}
fn entries(file:&std::path::Path)->Value{let mut zip=zip::ZipArchive::new(Cursor::new(std::fs::read(file).unwrap())).unwrap();let mut out=vec![];for i in 0..zip.len(){let mut entry=zip.by_index(i).unwrap();let mut bytes=vec![];entry.read_to_end(&mut bytes).unwrap();out.push(json!({"name":entry.name(),"method":entry.compression().to_u16(),"size":entry.size(),"crc":entry.crc32(),"bytes":base64(&bytes)}));}json!(out)}
fn strings(book:&Rc<KmoBook>,root:&std::path::Path)->Value{let mut out=vec![];for i in 0..3{if i==1{book.getCellValueStore().borrow_mut().newStringValue(Some("<&>\n\u{0000}_x0041_😀"));book.getCellValueStore().borrow_mut().newStringValue(Some(""));}let file=root.join("zips").join(format!("native-{i}.zip"));let mut pack=OxfwPackage::OxfwPackage(file.to_str().unwrap()).unwrap();let bp=XlsxwPackage::createBookPart(&mut pack,false,false);let writer=XlsxwSharedStrings::XlsxwSharedStrings(book.clone(),bp.getRelationships());let r=writer.write().unwrap();pack.close().unwrap();out.push(json!({"result":r,"entries":entries(&file)}));}json!(out)}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]
fn original_android_style_leaves_and_shared_strings_package(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/style-leaves-r0b37");
    let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();
    KmoLocale::setLocale(j["locale"].as_str().unwrap().into());
    // The two original Locale statics both initialize from the phone's default.
    // Replay that platform input before their original builtin-format initializer.
    kfc::cn::wps::kfc::numfmt::i18n::KmoLang::KmoLang::setLocale(j["locale"].as_str().unwrap().into());
    crate::cn::wps::moss::app::xf::KmoXFManager::KmoXFManager::loadBuiltinFormats();
    let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();
    let fills:Vec<_>=input["fills"].as_array().unwrap().iter().map(|source|{let p=pattern(source);output(|w|FillsLabel::writeFill(w,p.as_ref().map(|p|p.borrow()).as_deref(),source["condition"].as_bool().unwrap()))}).collect();let history=history(&input);let formats=formats(&input,&book);
    let mut types:Vec<_>=(i16::MIN..=i16::MAX).map(|v|json!(PatternTypeMap::getType(Some(v)))).collect();types.push(json!(result(||{PatternTypeMap::getType(None);})));crate::java_runtime::KfsZip::install();let strings=strings(&book,&p);
    let actual=json!({"locale":KmoLocale::getDefault(),"fills":fills,"history":history,"formats":formats,"types":types,"strings":strings});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&j,"root");
}
